function validate([s, t]) {
  if (s.length < 1 || s.length > 100) return 's must have 1 to 100 letters.';
  if (t.length < 1 || t.length > 100) return 't must have 1 to 100 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t may contain only lowercase letters.';
  return null;
}

