function countSubstrings(s, t) {
  let count = 0;
  for (let offset = 1 - t.length; offset < s.length; offset++) {
    let i = Math.max(offset, 0);
    let j = i - offset;
    let starts = 0;
    let run = 0;
    while (i < s.length && j < t.length) {
      run++;
      if (s[i] !== t[j]) {
        starts = run;
        run = 0;
      }
      count += starts;
      i++;
      j++;
    }
  }
  return count;
}

