function countSubstrings(s, t) {
  let total = 0;
  for (let len = 1; len <= Math.min(s.length, t.length); len++) {
    for (let a = 0; a + len <= s.length; a++) {
      for (let b = 0; b + len <= t.length; b++) {
        let differences = 0;
        for (let x = 0; x < len; x++) if (s[a + x] !== t[b + x]) differences++;
        if (differences === 1) total++;
      }
    }
  }
  return total;
}

