function generate(rand, size) {
  const word = (length, letters) => Array.from({ length }, () => String.fromCharCode(97 + Math.floor(rand() * letters))).join('');
  if (size === 'large') {
    const letters = [1, 2, 3, 26][Math.floor(rand() * 4)];
    return [word(80 + Math.floor(rand() * 21), letters), word(80 + Math.floor(rand() * 21), letters)];
  }
  const letters = 1 + Math.floor(rand() * 3);
  return [word(1 + Math.floor(rand() * 6), letters), word(1 + Math.floor(rand() * 6), letters)];
}
